<script setup lang="ts">
import UiIcon from'./NotebookIcon.vue';
import {onMounted,onBeforeUnmount,shallowRef,watch,ref}from'vue';import{Editor,EditorContent}from'@tiptap/vue-3';import StarterKit from'@tiptap/starter-kit';import{ReplaceStep}from'@tiptap/pm/transform';
import{entryFromScope,type Entry,type Course,type Scope}from'../editor/model';import type{NoteSelection}from'../editor/viewState';import{NotebookDocument,CourseGroup,LessonGroup,NoteCard,Reference,cardEditing,activeCard}from'../editor/extensions';import{toProjection,entriesFromProjection}from'../editor/projection';import{copyFragment,pasteFragment,requestPlainPaste}from'../editor/clipboard';
const props=defineProps<{entries:Entry[];courses:Course[];scope:Scope;collapsed:Set<string>;readonly:boolean;planId:string;sourceIds:string[]}>();
const emit=defineEmits<{change:[entries:Entry[],beforeIds:string[],typingGroup?:string];undo:[];redo:[];notice:[text:string];source:[sourceId:string,occurrenceId:string,rect:{x:number;y:number}];fold:[key:string];entryMenu:[id:string,x:number,y:number];composition:[active:boolean];save:[];view:[selection:NoteSelection]}>();
const editor=shallowRef<Editor>();const selectionVisible=ref(false);let ids:string[]=[];let timer:ReturnType<typeof setTimeout>|undefined;let replacing=false;let composing=false;let deferredProject=false;let emptyScope='',emptyEntry:Entry|undefined;function projectedDocument(){const key=JSON.stringify(props.scope);if(key!==emptyScope){emptyScope=key;emptyEntry=entryFromScope(props.scope)}return toProjection(props.entries,props.courses,props.scope,props.collapsed,emptyEntry)}
function project(){if(composing){deferredProject=true;return}if(!editor.value)return;const json=projectedDocument();if(JSON.stringify(editor.value.getJSON())===JSON.stringify(json))return;const old=editor.value.state.selection.from,selection=captureSelection();replacing=true;editor.value.commands.setContent(json,{emitUpdate:false});ids=entriesFromProjection(editor.value.getJSON()).map(e=>e.id);editor.value.commands.setTextSelection(Math.min(old,Math.max(1,editor.value.state.doc.content.size-1)));if(selection)restoreSelection(selection);replacing=false}
function peek(el:HTMLElement){const sourceId=el.dataset.noteSource,occurrenceId=el.dataset.occurrence;if(!sourceId||!occurrenceId)return;const r=el.getBoundingClientRect();emit('source',sourceId,occurrenceId,{x:r.left,y:r.bottom})}
onMounted(()=>{const initial=projectedDocument();ids=entriesFromProjection(initial).map(e=>e.id);
 editor.value=new Editor({extensions:[StarterKit.configure({document:false,undoRedo:false,trailingNode:false,link:false,codeBlock:false,blockquote:false,horizontalRule:false,underline:false,strike:false,heading:{levels:[2,3]}}),NotebookDocument,CourseGroup,LessonGroup,NoteCard,Reference,cardEditing(()=>props.scope,()=>emit('undo'),()=>emit('redo'))],content:initial,editable:!props.readonly,
 editorProps:{attributes:{class:'notebook-document',role:'textbox','aria-label':'连续笔记编辑器','aria-multiline':'true',spellcheck:'false'},handleDOMEvents:{keydown:(_view,event)=>{const e=event as KeyboardEvent;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();emit('save');return true}if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='v')requestPlainPaste();return false},copy:(view,event)=>copyFragment(editor.value!,event as ClipboardEvent,props.planId),cut:(view,event)=>{if(!copyFragment(editor.value!,event as ClipboardEvent,props.planId))return false;if(props.readonly)return true;editor.value!.view.dispatch(view.state.tr.deleteSelection().scrollIntoView());return true},drop:(_view,event)=>{const e=event as DragEvent;e.preventDefault();if(props.readonly)return true;const text=e.dataTransfer?.getData('text/plain');if(text)editor.value?.commands.insertContent(text.replace(/\r\n?/g,'\n').split('\n').map(t=>({type:'paragraph',...(t?{content:[{type:'text',text:t}]}:{})})));emit('notice','拖入内容按纯文字处理；引用移动请使用剪切／粘贴。');return true},paste:(_view,event)=>{if(props.readonly){event.preventDefault();return true}return pasteFragment(editor.value!,event as ClipboardEvent,text=>emit('notice',text),props.planId,new Set(props.sourceIds))},compositionstart:()=>{composing=true;emit('composition',true);return false},compositionend:()=>{setTimeout(()=>{composing=false;emit('composition',false);if(deferredProject){deferredProject=false;project()}},0);return false},mouseover:(_view,event)=>{const el=(event.target as HTMLElement).closest<HTMLElement>('[data-note-source]');if(el){clearTimeout(timer);timer=setTimeout(()=>peek(el),350)}return false},mouseout:()=>{clearTimeout(timer);return false},focusin:(_view,event)=>{const el=(event.target as HTMLElement).closest<HTMLElement>('[data-note-source]');if(el)peek(el);return false},click:(_view,event)=>{const target=event.target as HTMLElement;const fold=target.closest<HTMLElement>('[data-fold-key]');if(fold){emit('fold',fold.dataset.foldKey!);return true}const menu=target.closest<HTMLElement>('[data-entry-menu]');if(menu){const r=menu.getBoundingClientRect();emit('entryMenu',menu.dataset.entryMenu!,r.left,r.bottom);return true}return false}}},
 onUpdate:({editor:e,transaction:t})=>{if(replacing)return;const next=entriesFromProjection(e.getJSON());const before=[...ids];ids=next.map(x=>x.id);const step=t.steps[0];const typing=t.steps.length===1&&step instanceof ReplaceStep&&step.from===step.to&&step.slice.size<=2&&!t.getMeta('paste');emit('change',next,before,typing?activeCard(e)?.node.attrs.entryId:undefined)},onSelectionUpdate:({editor:e,transaction:t})=>{selectionVisible.value=!e.state.selection.empty;const selection=captureSelection();if(selection)emit('view',selection)}});
});
watch(()=>[props.entries,props.scope,props.collapsed,props.courses],project,{deep:true});watch(()=>props.readonly,v=>editor.value?.setEditable(!v));
onBeforeUnmount(()=>{clearTimeout(timer);editor.value?.destroy()});
function showSelectionSource(){const e=editor.value;if(!e)return;const m=e.state.selection.$from.marks().find(m=>m.type.name==='reference');if(m){const r=e.view.coordsAtPos(e.state.selection.from);emit('source',m.attrs.sourceId,m.attrs.occurrenceId,{x:r.left,y:r.bottom})}else emit('notice','请把光标放在引用文字中，或将鼠标停留在引用上。')}
function captureSelection():NoteSelection|null{const e=editor.value;if(!e)return null;const resolve=(pos:number)=>{const resolved=e.state.doc.resolve(pos);for(let d=resolved.depth;d>0;d--)if(resolved.node(d).type.name==='noteCard')return {id:resolved.node(d).attrs.entryId as string,offset:pos-resolved.before(d)};return null};const from=resolve(e.state.selection.from),to=resolve(e.state.selection.to);return from&&to?{fromId:from.id,fromOffset:from.offset,toId:to.id,toOffset:to.offset}:null}
function restoreSelection(selection?:NoteSelection){const e=editor.value;if(!e||!selection)return;let from:number|undefined,to:number|undefined;e.state.doc.descendants((node,pos)=>{if(node.type.name!=='noteCard')return;if(node.attrs.entryId===selection.fromId)from=pos+Math.min(node.nodeSize-2,Math.max(2,selection.fromOffset));if(node.attrs.entryId===selection.toId)to=pos+Math.min(node.nodeSize-2,Math.max(2,selection.toOffset))});if(from!==undefined&&to!==undefined)e.commands.setTextSelection({from,to})}
defineExpose({editor,project,showSelectionSource,captureSelection,restoreSelection});
</script>
<template><div class="editor-workspace"><div v-if="selectionVisible&&!readonly" class="selection-tools" role="toolbar" aria-label="选区格式"><button @mousedown.prevent="editor?.chain().focus().toggleBold().run()" title="加粗 Ctrl+B"><strong>B</strong></button><button @mousedown.prevent="editor?.chain().focus().toggleItalic().run()" title="斜体 Ctrl+I"><em>I</em></button><button @mousedown.prevent="editor?.chain().focus().toggleBulletList().run()" title="项目列表" aria-label="项目列表"><UiIcon name="list"/></button><button @mousedown.prevent="editor?.chain().focus().toggleHeading({level:2}).run()" title="小标题">H</button><button @mousedown.prevent="showSelectionSource" title="查看来源" aria-label="查看选区来源"><UiIcon name="expand"/></button></div><EditorContent :editor="editor"/></div></template>
